  const select = document.querySelector("#external-filter-select");
  let selectedValue = "";
  select.addEventListener("icClear", function (event) {
    select.options = [];
  });
  select.addEventListener("icOptionSelect", function (event) {
    selectedValue = event.detail.value;
  });
